}

/** Extensão a partir do último `.` do nome; nomes como `.bashrc` não têm. */
export function extname(p) {
  const base = basename(p);
  if (base === '..') return '';
  const idx = base.lastIndexOf('.');
  return idx <= 0 ? '' : base.slice(idx);
}

